import { useEffect, useMemo, useState } from "react";
import {
  ArrowUpLeft,
  Bell,
  Bug,
  Check,
  ChevronLeft,
  CircleHelp,
  Clock3,
  FileImage,
  Filter,
  LockKeyhole,
  LogOut,
  Menu,
  MoreHorizontal,
  Plus,
  Search,
  ShieldCheck,
  Sparkles,
  Trophy,
  Upload,
  UserRound,
  UsersRound,
  X,
} from "lucide-react";

type CaseStatus = "معتمدة" | "قيد المراجعة" | "مرفوضة";
type Session = { email: string; name: string; role: "owner" | "manager" | "admin" | "tester" };
type StaffAccount = { id: number; email: string; name: string; role: "admin" | "manager" | "owner" | "tester"; createdAt: string };
type ReviewCase = { id: string; admin: string; initials: string; action: string; target: string; date: string; status: CaseStatus; confidence: number; points: number };

const cases: ReviewCase[] = [];
const leaderboard: Array<{ name: string; role: string; points: number; color: string }> = [];

function StatusPill({ status }: { status: CaseStatus }) {
  const styles: Record<CaseStatus, string> = { معتمدة: "bg-[#e5f7ed] text-[#147447]", "قيد المراجعة": "bg-[#fff3dc] text-[#a35c00]", مرفوضة: "bg-[#ffebea] text-[#bb3a35]" };
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold ${styles[status]}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{status}</span>;
}

function StatCard({ label, value, detail, icon, tone }: { label: string; value: string; detail: string; icon: React.ReactNode; tone: string }) {
  return <div className="rounded-2xl border border-[#e5e8ee] bg-white p-5 shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="mb-5 flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${tone}`}>{icon}</div><MoreHorizontal className="h-5 w-5 text-[#aab1bc]" /></div><p className="text-sm text-[#697386]">{label}</p><div className="mt-1 flex items-end gap-2"><strong className="text-3xl font-extrabold tracking-tight text-[#1d2736]">{value}</strong><span className="mb-1 text-xs font-bold text-[#2d9b67]">{detail}</span></div></div>;
}

function LoginView({ onLogin }: { onLogin: (email: string, password: string) => Promise<void> }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  return <div dir="rtl" className="min-h-screen bg-[#f7f8fb] text-[#1d2736]"><div className="mx-auto flex min-h-screen max-w-6xl items-center justify-center px-5 py-10"><div className="grid w-full max-w-5xl overflow-hidden rounded-[28px] border border-[#e5e8ee] bg-white shadow-[0_24px_70px_rgba(35,52,80,0.12)] lg:grid-cols-[1.05fr_0.95fr]"><div className="relative hidden overflow-hidden bg-[#102241] p-12 text-white lg:block"><div className="absolute -left-24 -top-24 h-72 w-72 rounded-full bg-[#3465cf]/30 blur-3xl" /><div className="absolute -bottom-32 -right-20 h-80 w-80 rounded-full bg-[#52c58d]/20 blur-3xl" /><div className="relative flex h-full flex-col justify-between"><div><div className="mb-16 flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#4e7df2] shadow-lg shadow-[#4e7df2]/30"><ShieldCheck className="h-6 w-6" /></div><div><div className="text-xl font-black">voidsmp</div><div className="text-xs text-[#afc0de]">مراجعة أعمال الإدارة</div></div></div><p className="max-w-sm text-4xl font-black leading-[1.2]">قرار إداري أوضح.<br /><span className="text-[#83a8ff]">نظام نقاط أعدل.</span></p><p className="mt-6 max-w-sm text-sm leading-7 text-[#b4c0db]">ارفع دليل الإجراء، ودع التحليل الذكي يجهّز لك مراجعة قابلة للتدقيق.</p></div><div className="flex items-center gap-3 text-sm text-[#c6d2e8]"><Sparkles className="h-4 w-4 text-[#80d9ac]" /> التحليل الذكي لا يعتمد الحالات غير الواضحة تلقائيًا</div></div></div><div className="p-8 sm:p-12"><div className="mb-10 flex items-center gap-3 lg:hidden"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#3465cf] text-white"><ShieldCheck className="h-5 w-5" /></div><strong>voidsmp</strong></div><div className="mb-9"><p className="mb-3 text-sm font-bold text-[#3465cf]">منطقة الإدارة</p><h1 className="text-3xl font-black tracking-tight">أهلًا بعودتك</h1><p className="mt-3 text-sm leading-6 text-[#697386]">سجّل الدخول لمتابعة الحالات ونقاط فريق الإدارة.</p></div><form onSubmit={async (event) => { event.preventDefault(); setError(""); setLoading(true); try { await onLogin(email, password); } catch (loginError) { setError(loginError instanceof Error ? loginError.message : "تعذر تسجيل الدخول"); } finally { setLoading(false); } }} className="space-y-5"><label className="block"><span className="mb-2 block text-sm font-bold">البريد الإلكتروني</span><div className="relative"><UserRound className="absolute right-3 top-3.5 h-4 w-4 text-[#9ba5b5]" /><input required dir="ltr" type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="admin@example.com" className="h-11 w-full rounded-xl border border-[#dfe4eb] bg-[#fbfcfe] px-10 text-sm outline-none transition focus:border-[#4e7df2] focus:ring-4 focus:ring-[#4e7df2]/10" /></div></label><label className="block"><span className="mb-2 block text-sm font-bold">كلمة المرور</span><div className="relative"><LockKeyhole className="absolute right-3 top-3.5 h-4 w-4 text-[#9ba5b5]" /><input required dir="ltr" type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="••••••••" className="h-11 w-full rounded-xl border border-[#dfe4eb] bg-[#fbfcfe] px-10 text-sm outline-none transition focus:border-[#4e7df2] focus:ring-4 focus:ring-[#4e7df2]/10" /></div></label><div className="flex items-center justify-between text-xs"><label className="flex items-center gap-2 text-[#697386]"><input type="checkbox" className="accent-[#3465cf]" /> تذكرني</label><button type="button" className="font-bold text-[#3465cf]">نسيت كلمة المرور؟</button></div>{error && <div className="rounded-xl bg-[#ffebea] px-3 py-2 text-xs font-bold text-[#bb3a35]">{error}</div>}<button disabled={loading} className="mt-3 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#3465cf] font-bold text-white shadow-lg shadow-[#3465cf]/20 transition hover:bg-[#2856bd] disabled:cursor-wait disabled:opacity-70">{loading ? "جارٍ التحقق..." : "دخول إلى اللوحة"} {!loading && <ChevronLeft className="h-4 w-4" />}</button></form><p className="mt-8 text-center text-xs text-[#9ba5b5]">الوصول مخصص لأعضاء فريق الإدارة المصرح لهم</p></div></div></div></div>;
}

function TesterStatsPanel({ session }: { session: Session }) {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { fetch("/api/tester-stats").then(async (response) => { const result = await response.json(); if (!response.ok) throw new Error(result.error ?? "تعذر تحميل إحصائيات Testers"); setData(result); }).catch((loadError) => setError(loadError instanceof Error ? loadError.message : "تعذر تحميل الإحصائيات")).finally(() => setLoading(false)); }, []);
  const canSeeAll = session.role === "manager" || session.role === "owner";
  return <section className="space-y-6"><div className="rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-6"><div className="flex items-center gap-2 text-sm font-bold text-[#3465cf]"><Trophy className="h-4 w-4" /> إحصائيات Testers</div><h2 className="mt-2 text-2xl font-black">{canSeeAll ? "أداء فريق الاختبار" : "إحصائياتك كـ Tester"}</h2><p className="mt-2 text-sm text-[#697386]">{canSeeAll ? "تابع نقاط كل Testers وترتيبهم من الحالات المعتمدة." : "تابع نقاطك وترتيب أفضل 5 Testers."}</p></div>{error && <div className="rounded-xl bg-[#ffebea] px-4 py-3 text-sm font-bold text-[#bb3a35]">{error}</div>}{loading ? <div className="rounded-2xl border border-[#e5e8ee] bg-white p-10 text-center text-sm text-[#697386]">جارٍ تحميل الإحصائيات...</div> : data && <><div className="grid gap-4 sm:grid-cols-3"><StatCard label="نقاطك" value={String(data.own.points)} detail="من الحالات المعتمدة" icon={<Trophy className="h-5 w-5 text-[#3465cf]" />} tone="bg-[#edf3ff]" /><StatCard label="حالاتك المعتمدة" value={String(data.own.approvedCases)} detail={`من ${data.own.totalCases} حالة`} icon={<Check className="h-5 w-5 text-[#18794e]" />} tone="bg-[#e5f7ed]" /><StatCard label="ترتيبك" value={data.leaderboard.findIndex((tester: any) => tester.email === data.own.email) >= 0 ? `#${data.leaderboard.findIndex((tester: any) => tester.email === data.own.email) + 1}` : "—"} detail="ضمن أفضل 5" icon={<UsersRound className="h-5 w-5 text-[#7842a8]" />} tone="bg-[#f2e6ff]" /></div><div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">أفضل 5 Testers</h3><p className="mt-1 text-xs text-[#9ba5b5]">الترتيب ظاهر لفريق الاختبار والإدارة</p></div>{data.leaderboard.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد نقاط Testers حتى الآن.</div> : <div className="divide-y divide-[#f0f2f5]">{data.leaderboard.map((tester: any, index: number) => <div key={tester.email} className="flex items-center gap-4 p-4"><div className={`flex h-9 w-9 items-center justify-center rounded-full text-sm font-black ${index === 0 ? "bg-[#fff0c7] text-[#a56600]" : "bg-[#edf3ff] text-[#3465cf]"}`}>{index + 1}</div><div className="flex-1"><div className="text-sm font-black">{tester.name}</div><div className="mt-1 text-xs text-[#697386]">{tester.approvedCases} حالات معتمدة · {tester.totalCases} إجمالي</div></div><div className="text-left"><div className="text-xl font-black text-[#1d2736]">{tester.points}</div><div className="text-[10px] text-[#9ba5b5]">نقطة</div></div></div>)}</div>}</div>{canSeeAll && <div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">كل Testers</h3><p className="mt-1 text-xs text-[#9ba5b5]">كشف كامل متاح للـ Manager والـ Owner فقط.</p></div>{data.all.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد حسابات Tester بعد.</div> : <div className="divide-y divide-[#f0f2f5]">{data.all.map((tester: any) => <div key={tester.email} className="flex items-center gap-4 p-4"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-[#f2e6ff] text-sm font-black text-[#7842a8]">{tester.name.slice(0, 2)}</div><div className="flex-1"><div className="text-sm font-black">{tester.name}</div><div className="mt-1 text-xs text-[#697386]">{tester.email}</div></div><div className="text-left"><div className="text-lg font-black">{tester.points}</div><div className="text-[10px] text-[#9ba5b5]">نقطة · {tester.approvedCases} معتمدة</div></div></div>)}</div>}</div>}</>}</section>;
}

function BugReportsPanel({ session }: { session: Session }) {
  const [reports, setReports] = useState<any[]>([]);
  const [form, setForm] = useState({ title: "", description: "", severity: "medium" });
  const [statusDrafts, setStatusDrafts] = useState<Record<number, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const canReview = session.role === "manager" || session.role === "owner";
  const loadReports = async () => { const response = await fetch("/api/bug-reports"); const data = await response.json(); if (!response.ok) throw new Error(data.error ?? "تعذر تحميل البلاغات"); setReports(data.reports ?? []); setStatusDrafts(Object.fromEntries((data.reports ?? []).map((report: any) => [report.id, report.status]))); };
  useEffect(() => { loadReports().catch((loadError) => setError(loadError.message)).finally(() => setLoading(false)); }, []);
  const submitReport = async (event: React.FormEvent) => { event.preventDefault(); setError(""); setNotice(""); setSaving(true); try { const response = await fetch("/api/bug-reports", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) throw new Error(data.error ?? "تعذر إرسال البلاغ"); setReports((current) => [data.report, ...current]); setForm({ title: "", description: "", severity: "medium" }); setNotice("تم إرسال البلاغ للمراجعة"); } catch (submitError) { setError(submitError instanceof Error ? submitError.message : "تعذر إرسال البلاغ"); } finally { setSaving(false); } };
  const reviewReport = async (id: number) => { const status = statusDrafts[id] ?? "in_review"; const reviewNote = window.prompt("اكتب ملاحظة المراجعة (اختياري):") ?? ""; setError(""); setNotice(""); setSaving(true); try { const response = await fetch(`/api/bug-reports/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status, reviewNote }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error ?? "تعذر حفظ المراجعة"); setReports((current) => current.map((report) => report.id === id ? data.report : report)); setNotice("تم تحديث حالة البلاغ"); } catch (reviewError) { setError(reviewError instanceof Error ? reviewError.message : "تعذر حفظ المراجعة"); } finally { setSaving(false); } };
  const statusLabel = (status: string) => ({ open: "مفتوح", in_review: "قيد المراجعة", resolved: "تم الحل", rejected: "مرفوض" } as Record<string, string>)[status] ?? status;
  const severityLabel = (severity: string) => ({ low: "منخفض", medium: "متوسط", high: "مرتفع", critical: "حرج" } as Record<string, string>)[severity] ?? severity;
  return <section className="space-y-6"><div className="rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-6"><div className="flex items-center gap-2 text-sm font-bold text-[#3465cf]"><Bug className="h-4 w-4" /> بلاغات الجلتشات والـ Bugs</div><h2 className="mt-2 text-2xl font-black">{canReview ? "مراجعة بلاغات الاختبار" : "غرفة اختبار السيرفر"}</h2><p className="mt-2 text-sm text-[#697386]">{canReview ? "راجع البلاغات الواردة من الـ Testers وحدد إن كانت مفتوحة أو قيد المراجعة أو تم حلها." : "اكتب أي جلِتش أو Bug تلاحظه في السيرفر ليتم مراجعته من الإدارة."}</p></div>{notice && <div className="rounded-xl bg-[#e5f7ed] px-4 py-3 text-sm font-bold text-[#147447]">{notice}</div>}{error && <div className="rounded-xl bg-[#ffebea] px-4 py-3 text-sm font-bold text-[#bb3a35]">{error}</div>}{!canReview && <form onSubmit={submitReport} className="rounded-2xl border border-[#e5e8ee] bg-white p-6 shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><h3 className="font-black">إرسال بلاغ جديد</h3><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-sm font-bold">عنوان المشكلة</span><input required minLength={3} value={form.title} onChange={(event) => setForm({ ...form, title: event.target.value })} placeholder="مثال: زر رفع الصورة لا يستجيب" className="h-11 w-full rounded-xl border border-[#dfe4eb] bg-[#fbfcfe] px-3 text-sm outline-none focus:border-[#3465cf]" /></label><label className="block"><span className="mb-2 block text-sm font-bold">الأولوية</span><select value={form.severity} onChange={(event) => setForm({ ...form, severity: event.target.value })} className="h-11 w-full rounded-xl border border-[#dfe4eb] bg-white px-3 text-sm font-bold text-[#697386] outline-none focus:border-[#3465cf]"><option value="low">منخفض</option><option value="medium">متوسط</option><option value="high">مرتفع</option><option value="critical">حرج</option></select></label></div><label className="mt-4 block"><span className="mb-2 block text-sm font-bold">وصف الجلتش</span><textarea required minLength={10} value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} rows={5} placeholder="اكتب خطوات ظهور المشكلة والنتيجة التي ظهرت لك..." className="w-full resize-y rounded-xl border border-[#dfe4eb] bg-[#fbfcfe] p-3 text-sm leading-6 outline-none focus:border-[#3465cf]" /></label><button disabled={saving} className="mt-5 flex h-11 items-center justify-center gap-2 rounded-xl bg-[#3465cf] px-5 text-sm font-bold text-white disabled:opacity-60"><Bug className="h-4 w-4" /> إرسال للمراجعة</button></form>}<div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">{canReview ? "كل بلاغات الـ Testers" : "بلاغاتي"}</h3><p className="mt-1 text-xs text-[#9ba5b5]">كل بلاغ يحتفظ بصاحبه ووقته وحالة المراجعة.</p></div>{loading ? <div className="p-8 text-center text-sm text-[#697386]">جارٍ تحميل البلاغات...</div> : reports.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد بلاغات حتى الآن.</div> : <div className="divide-y divide-[#f0f2f5]">{reports.map((report) => <article key={report.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#edf3ff] text-[#3465cf]"><Bug className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h4 className="text-sm font-black">{report.title}</h4><span className="rounded-full bg-[#fff3dc] px-2 py-1 text-[10px] font-bold text-[#a35c00]">{severityLabel(report.severity)}</span><span className="rounded-full bg-[#edf3ff] px-2 py-1 text-[10px] font-bold text-[#3465cf]">{statusLabel(report.status)}</span></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[#697386]">{report.description}</p><div className="mt-3 text-xs text-[#9ba5b5]">بواسطة {report.reporterName} · {new Intl.DateTimeFormat("ar-EG", { dateStyle: "medium", timeStyle: "short" }).format(new Date(report.createdAt))}</div>{report.reviewNote && <div className="mt-3 rounded-xl bg-[#f5f8ff] p-3 text-xs leading-5 text-[#52647e]"><strong>ملاحظة المراجعة:</strong> {report.reviewNote}</div>}</div>{canReview && <div className="flex shrink-0 items-center gap-2"><select value={statusDrafts[report.id] ?? report.status} onChange={(event) => setStatusDrafts((current) => ({ ...current, [report.id]: event.target.value }))} className="h-9 rounded-lg border border-[#dfe4eb] bg-white px-2 text-xs font-bold text-[#697386]"><option value="open">مفتوح</option><option value="in_review">قيد المراجعة</option><option value="resolved">تم الحل</option><option value="rejected">مرفوض</option></select><button type="button" disabled={saving} onClick={() => reviewReport(report.id)} className="h-9 rounded-lg bg-[#3465cf] px-3 text-xs font-bold text-white disabled:opacity-60">حفظ المراجعة</button></div>}</div></article>)}</div>}</div></section>;
}

function StaffDetailsPanel() {
  const [people, setPeople] = useState<Array<{ email: string; name: string; points: number; approvedCases: number }>>([]);
  const [selectedEmail, setSelectedEmail] = useState("");
  const [details, setDetails] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { fetch("/api/points").then((response) => response.json()).then((data) => { const list = data.all ?? []; setPeople(list); setSelectedEmail(list[0]?.email ?? ""); }).catch(() => setError("تعذر تحميل قائمة الإداريين")).finally(() => setLoading(false)); }, []);
  useEffect(() => { if (!selectedEmail) return; setLoading(true); setError(""); fetch(`/api/staff-details?email=${encodeURIComponent(selectedEmail)}`).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error ?? "تعذر تحميل التفاصيل"); setDetails(data); }).catch((loadError) => setError(loadError instanceof Error ? loadError.message : "تعذر تحميل التفاصيل")).finally(() => setLoading(false)); }, [selectedEmail]);
  const formatDate = (value: string) => new Intl.DateTimeFormat("ar-EG", { year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
  return <section className="space-y-6"><div className="rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-6"><div className="flex items-center gap-2 text-sm font-bold text-[#3465cf]"><Search className="h-4 w-4" /> ملف الإداري</div><h2 className="mt-2 text-2xl font-black">تفاصيل أداء الإداري</h2><p className="mt-2 text-sm text-[#697386]">اختر إداريًا لمراجعة كل ما رفعه، نوع المهام، النقاط، ووقت اعتماد كل نقطة.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-center"><label className="text-sm font-bold">اسم الإداري</label><select value={selectedEmail} onChange={(event) => setSelectedEmail(event.target.value)} className="h-11 min-w-64 rounded-xl border border-[#dfe4eb] bg-white px-3 text-sm font-bold text-[#697386] outline-none focus:border-[#3465cf]"><option value="">اختر إداريًا</option>{people.map((person) => <option key={person.email} value={person.email}>{person.name} — {person.email}</option>)}</select></div></div>{error && <div className="rounded-xl bg-[#ffebea] px-4 py-3 text-sm font-bold text-[#bb3a35]">{error}</div>}{loading && !details ? <div className="rounded-2xl border border-[#e5e8ee] bg-white p-10 text-center text-sm text-[#697386]">جارٍ تحميل الملف...</div> : details && <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard label="إجمالي النقاط" value={String(details.summary.points)} detail="من الحالات المعتمدة" icon={<Trophy className="h-5 w-5 text-[#3465cf]" />} tone="bg-[#edf3ff]" /><StatCard label="الحالات الكلية" value={String(details.summary.totalCases)} detail="كل ما تم رفعه" icon={<FileImage className="h-5 w-5 text-[#7842a8]" />} tone="bg-[#f2e6ff]" /><StatCard label="المعتمدة" value={String(details.summary.approvedCases)} detail="تم احتسابها" icon={<Check className="h-5 w-5 text-[#18794e]" />} tone="bg-[#e5f7ed]" /><StatCard label="تحتاج مراجعة" value={String(details.summary.pendingCases)} detail="لم تعتمد بعد" icon={<Clock3 className="h-5 w-5 text-[#a56600]" />} tone="bg-[#fff3dc]" /><StatCard label="المرفوضة" value={String(details.summary.rejectedCases)} detail="لم تحتسب" icon={<X className="h-5 w-5 text-[#bb3a35]" />} tone="bg-[#ffebea]" /></div><div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">توزيع المهام</h3><p className="mt-1 text-xs text-[#9ba5b5]">عدد المهام والنقاط حسب نوع الإجراء</p></div>{details.summary.byAction.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد مهام مسجلة لهذا الإداري.</div> : <div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-3">{details.summary.byAction.map((item: any) => <div key={item.label} className="rounded-xl border border-[#edf0f4] bg-[#fbfcfe] p-4"><div className="flex items-center justify-between"><span className="text-sm font-black">{item.label}</span><span className="rounded-full bg-[#edf3ff] px-2 py-1 text-[11px] font-bold text-[#3465cf]">{item.points} نقطة</span></div><p className="mt-2 text-xs text-[#697386]">{item.count} حالة</p></div>)}</div>}</div><div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">سجل النقاط والمهام</h3><p className="mt-1 text-xs text-[#9ba5b5]">كل نقطة موضّح معها النوع والتاريخ والساعة والدقيقة</p></div>{details.cases.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد حالات لهذا الإداري.</div> : <div className="divide-y divide-[#f0f2f5]">{details.cases.map((item: any) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#edf3ff] text-[#3465cf]"><FileImage className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-black">{item.actionLabel}</span><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${item.status === "approved" ? "bg-[#e5f7ed] text-[#147447]" : item.status === "pending_review" ? "bg-[#fff3dc] text-[#a35c00]" : "bg-[#ffebea] text-[#bb3a35]"}`}>{item.status === "approved" ? "معتمدة" : item.status === "pending_review" ? "قيد المراجعة" : item.status}</span></div><div className="mt-1 text-xs text-[#697386]">{item.targetUser ? `على العضو: ${item.targetUser} · ` : ""}{item.originalName}</div><div className="mt-2 text-xs leading-5 text-[#697386]">{item.reason ?? "لا يوجد وصف إضافي"}</div></div><div className="shrink-0 text-right"><div className="text-lg font-black text-[#3465cf]">{item.pointsGranted} نقطة</div><div className="mt-1 text-[11px] text-[#697386]">{formatDate(item.createdAt)}</div></div></div>)}</div>}</div></>}</section>;
}

function AccountsPanel({ session }: { session: Session }) {
  const [accounts, setAccounts] = useState<StaffAccount[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const loadAccounts = async () => { const response = await fetch("/api/admin/accounts"); if (!response.ok) throw new Error("تعذر تحميل الحسابات"); const data = await response.json(); setAccounts(data.accounts ?? []); };
  const updateRole = async (id: number, role: StaffAccount["role"]) => { setError(""); const response = await fetch(`/api/admin/accounts/${id}/role`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ role }) }); const data = await response.json(); if (!response.ok) { setError(data.error ?? "تعذر تعديل الرتبة"); return; } setAccounts((current) => current.map((account) => account.id === id ? { ...account, role: data.account.role } : account)); setNotice("تم تعديل رتبة الحساب"); };
  const resetPassword = async (id: number) => { const password = window.prompt("أدخل كلمة مرور جديدة للحساب، 10 أحرف على الأقل:"); if (!password) return; setError(""); const response = await fetch(`/api/admin/accounts/${id}/password`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ password }) }); const data = await response.json(); if (!response.ok) { setError(data.error ?? "تعذر تغيير كلمة المرور"); return; } setNotice("تم تغيير كلمة مرور الحساب"); };
  useEffect(() => { if (session.role === "owner") loadAccounts().catch((loadError) => setError(loadError.message)); }, [session.role]);
  if (session.role !== "owner") return <div className="rounded-2xl border border-[#ffe0b0] bg-[#fff8ea] p-6"><h2 className="text-xl font-black">إدارة الحسابات</h2><p className="mt-2 text-sm text-[#8c650e]">إنشاء حسابات الإداريين متاح لحساب المالك فقط.</p></div>;
  const createAccount = async (event: React.FormEvent) => { event.preventDefault(); setNotice(""); setError(""); const response = await fetch("/api/admin/accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) { setError(data.error ?? "تعذر إنشاء الحساب"); return; } setAccounts((current) => [data.account, ...current]); setForm({ name: "", email: "", password: "" }); setShowForm(false); setNotice("تم إنشاء حساب الإداري بنجاح"); };
  return <section className="space-y-6"><div className="flex flex-col justify-between gap-4 rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-6 md:flex-row md:items-center"><div><div className="flex items-center gap-2 text-sm font-bold text-[#3465cf]"><ShieldCheck className="h-4 w-4" /> صلاحية المالك</div><h2 className="mt-2 text-2xl font-black">حسابات فريق الإدارة</h2><p className="mt-2 text-sm text-[#697386]">من هنا تنشئ حسابات الدخول وتعدل الرتبة أو كلمة المرور لكل حساب.</p></div><button onClick={() => setShowForm(true)} className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#3465cf] px-5 text-sm font-bold text-white shadow-lg shadow-[#3465cf]/20"><Plus className="h-4 w-4" /> إنشاء حساب إداري</button></div>{notice && <div className="flex items-center gap-2 rounded-xl bg-[#e5f7ed] px-4 py-3 text-sm font-bold text-[#147447]"><Check className="h-4 w-4" /> {notice}</div>}{error && <div className="rounded-xl bg-[#ffebea] px-4 py-3 text-sm font-bold text-[#bb3a35]">{error}</div>}<div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">المستخدمون المصرح لهم</h3><p className="mt-1 text-xs text-[#9ba5b5]">المالك والإداريون الذين يمكنهم الدخول إلى النظام</p></div><div className="divide-y divide-[#f0f2f5]"><div className="flex items-center gap-3 p-5"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-[#dce9ff] text-[#2458b8]"><ShieldCheck className="h-5 w-5" /></div><div className="flex-1"><div className="text-sm font-black">مالك النظام</div><div className="mt-1 text-xs text-[#697386]">{session.email}</div></div><span className="rounded-full bg-[#edf3ff] px-3 py-1 text-xs font-bold text-[#3465cf]">Owner</span></div>{accounts.map((account) => <div key={account.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-[#e5f7ed] text-sm font-black text-[#18794e]">{account.name.slice(0, 2)}</div><div className="flex-1"><div className="text-sm font-black">{account.name}</div><div className="mt-1 text-xs text-[#697386]">{account.email}</div></div><div className="flex items-center gap-2"><select value={account.role} onChange={(event) => updateRole(account.id, event.target.value as StaffAccount["role"])} className="h-9 rounded-lg border border-[#dfe4eb] bg-white px-3 text-xs font-bold text-[#697386] outline-none focus:border-[#3465cf]"><option value="admin">Admin</option><option value="manager">Manager</option><option value="owner">Owner</option><option value="tester">Tester</option></select><button type="button" onClick={() => resetPassword(account.id)} className="h-9 rounded-lg border border-[#dfe4eb] px-3 text-xs font-bold text-[#697386] hover:border-[#3465cf] hover:text-[#3465cf]">تغيير كلمة المرور</button></div></div>)}</div></div>{showForm && <div className="fixed inset-0 z-30 flex items-center justify-center bg-[#0d1d38]/35 px-5 backdrop-blur-sm"><form onSubmit={createAccount} className="w-full max-w-md rounded-3xl bg-white p-6 shadow-2xl"><div className="mb-6 flex items-center justify-between"><div><h3 className="text-xl font-black">إنشاء حساب إداري</h3><p className="mt-1 text-xs text-[#9ba5b5]">الحساب سيبدأ برتبة Admin ويمكن تغييرها لاحقًا.</p></div><button type="button" onClick={() => setShowForm(false)} className="rounded-lg p-2 text-[#9ba5b5] hover:bg-[#f5f7fa]"><X className="h-5 w-5" /></button></div><div className="space-y-4"><label className="block"><span className="mb-2 block text-sm font-bold">اسم الإداري</span><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} className="h-11 w-full rounded-xl border border-[#dfe4eb] px-3 text-sm outline-none focus:border-[#3465cf]" /></label><label className="block"><span className="mb-2 block text-sm font-bold">البريد الإلكتروني</span><input required type="email" dir="ltr" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} className="h-11 w-full rounded-xl border border-[#dfe4eb] px-3 text-sm outline-none focus:border-[#3465cf]" /></label><label className="block"><span className="mb-2 block text-sm font-bold">كلمة المرور</span><input required minLength={10} type="password" dir="ltr" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} className="h-11 w-full rounded-xl border border-[#dfe4eb] px-3 text-sm outline-none focus:border-[#3465cf]" /><span className="mt-1 block text-[11px] text-[#9ba5b5]">10 أحرف على الأقل</span></label></div><button className="mt-6 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-[#3465cf] text-sm font-bold text-white"><Plus className="h-4 w-4" /> حفظ الحساب</button></form></div>}</section>;
}

function RecordsPanel({ title, description, review, canOpen }: { title: string; description: string; review?: boolean; canOpen?: boolean }) {
  const [records, setRecords] = useState<Array<{ id: number; adminName: string; originalName: string; storageUrl: string; status: string; actionType: string | null; targetUser: string | null; confidence: number | null; reason: string | null; pointsGranted: number; createdAt: string }>>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => { fetch(`/api/reviews${review ? "?status=pending_review" : ""}`).then((response) => response.json()).then((data) => setRecords(data.reviews ?? [])).finally(() => setLoading(false)); }, [review]);
  return <section className="rounded-2xl border border-[#e5e8ee] bg-white p-6 shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="mb-6 flex items-center gap-4"><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#edf3ff] text-[#3465cf]">{review ? <Clock3 className="h-7 w-7" /> : <FileImage className="h-7 w-7" />}</div><div><h2 className="text-xl font-black">{title}</h2><p className="mt-1 text-sm text-[#697386]">{description}</p></div></div>{loading ? <div className="rounded-xl bg-[#f7f8fb] px-4 py-6 text-center text-sm text-[#697386]">جارٍ تحميل الحالات...</div> : records.length === 0 ? <div className="rounded-xl bg-[#f7f8fb] px-4 py-6 text-center text-sm text-[#697386]">لا توجد حالات حقيقية في هذه القائمة حاليًا.</div> : <div className="space-y-3">{records.map((record) => <div key={record.id} className="flex flex-col gap-3 rounded-xl border border-[#edf0f4] p-4 sm:flex-row sm:items-center"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#edf3ff] text-[#3465cf]"><FileImage className="h-5 w-5" /></div><div className="flex-1"><div className="text-sm font-black">{record.actionType ?? "بانتظار التحليل"}{record.targetUser ? ` — ${record.targetUser}` : ""}</div><div className="mt-1 text-xs text-[#697386]">{record.originalName} · رفعها {record.adminName}</div><div className="mt-1 text-xs text-[#9ba5b5]">{record.reason ?? "جاري تحليل الصورة"}</div></div><div className="text-right text-xs"><div className="font-black text-[#3465cf]">{record.confidence ?? 0}% ثقة</div><div className="mt-1 text-[#697386]">{record.pointsGranted} نقطة</div>{canOpen && record.storageUrl && <a href={record.storageUrl} target="_blank" rel="noreferrer" className="mt-2 inline-block font-bold text-[#3465cf] hover:underline">فتح الصورة</a>}</div></div>)}</div>}</section>;
}

function Dashboard({ onUpload }: { onUpload: () => void }) {
  const [records, setRecords] = useState<Array<{ id: number; adminName: string; originalName: string; status: string; actionType: string | null; targetUser: string | null; confidence: number | null; reason: string | null; pointsGranted: number }>>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => { fetch("/api/reviews").then((response) => response.json()).then((data) => setRecords(data.reviews ?? [])).finally(() => setLoading(false)); }, []);
  const approved = records.filter((record) => record.status === "approved");
  const pending = records.filter((record) => record.status === "pending_review" || record.status === "processing");
  const points = records.reduce((sum, record) => sum + (record.pointsGranted ?? 0), 0);
  const confidenceValues = records.filter((record) => typeof record.confidence === "number" && record.confidence > 0).map((record) => record.confidence as number);
  const averageConfidence = confidenceValues.length ? `${Math.round(confidenceValues.reduce((sum, value) => sum + value, 0) / confidenceValues.length)}%` : "—";
  return <><section className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mb-2 flex items-center gap-2 text-sm font-bold text-[#3465cf]"><span className="h-2 w-2 rounded-full bg-[#4fc58b]" /> النظام يعمل بشكل طبيعي</p><h2 className="text-3xl font-black tracking-tight">لوحة المراجعة <span className="text-[#b8c0cd">—</span></h2><p className="mt-2 text-sm text-[#697386]">الأرقام التالية محسوبة من الحالات المحفوظة فعليًا.</p></div><button onClick={onUpload} className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#3465cf] px-5 text-sm font-bold text-white shadow-lg shadow-[#3465cf]/20"><Upload className="h-4 w-4" /> رفع حالة جديدة</button></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="إجمالي النقاط المكتسبة" value={String(points)} detail={points ? "من حالات معتمدة" : "لا توجد بيانات"} icon={<Trophy className="h-5 w-5 text-[#3465cf]" />} tone="bg-[#edf3ff]" /><StatCard label="حالات تمت مراجعتها" value={String(approved.length)} detail={approved.length ? "حالة معتمدة" : "لا توجد بيانات"} icon={<FileImage className="h-5 w-5 text-[#18794e]" />} tone="bg-[#e5f7ed]" /><StatCard label="بانتظار قرار" value={String(pending.length)} detail={pending.length ? "تحتاج انتباهك" : "لا توجد بيانات"} icon={<Clock3 className="h-5 w-5 text-[#a56600]" />} tone="bg-[#fff3dc]" /><StatCard label="متوسط دقة التحليل" value={averageConfidence} detail={confidenceValues.length ? "من الحالات المحللة" : "بعد أول تحليل"} icon={<Sparkles className="h-5 w-5 text-[#7842a8]" />} tone="bg-[#f2e6ff]" /></section><section className="mt-7 rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="flex items-center justify-between border-b border-[#edf0f4] p-5"><div><h3 className="font-black">آخر الحالات</h3><p className="mt-1 text-xs text-[#9ba5b5]">كل عنصر هنا مصدره قاعدة البيانات</p></div><button onClick={() => window.location.reload()} className="text-xs font-bold text-[#3465cf]">تحديث</button></div>{loading ? <div className="p-10 text-center text-sm text-[#697386]">جارٍ تحميل البيانات...</div> : records.length === 0 ? <div className="p-10 text-center"><FileImage className="mx-auto h-10 w-10 text-[#b4bdca]" /><h4 className="mt-4 font-black">لا توجد حالات محفوظة بعد</h4><p className="mt-2 text-sm text-[#697386]">ارفع أول صورة لتظهر هنا بعد تأكيد الرفع.</p></div> : <div className="divide-y divide-[#f0f2f5]">{records.slice(0, 8).map((record) => <div key={record.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3ff] text-[#3465cf]"><FileImage className="h-4 w-4" /></div><div className="flex-1"><div className="text-sm font-black">{record.actionType ?? "بانتظار التحليل"}{record.targetUser ? ` — ${record.targetUser}` : ""}</div><div className="mt-1 text-xs text-[#697386]">{record.originalName} · {record.adminName}</div></div><div className="text-right text-xs"><div className="font-black text-[#3465cf]">{record.pointsGranted} نقطة</div><div className="mt-1 text-[#697386]">{record.status === "approved" ? "معتمدة" : record.status === "pending_review" ? "تحتاج مراجعة" : "جاري التحليل"}</div></div></div>)}</div>}</section><section className="mt-6 flex items-center gap-3 rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-4 text-sm"><Sparkles className="h-5 w-5 shrink-0 text-[#3465cf]" /><p className="leading-6 text-[#52647e]"><strong className="text-[#1e4fa9]">سياسة النقاط:</strong> لا تُضاف نقطة إلا للحالة التي يثبت فيها التحليل إجراءً واضحًا بثقة 85% أو أكثر. الحالات غير الواضحة تبقى في المراجعة.</p></section></>;
}

function PointsPanel({ session }: { session: Session }) {
  const [leaderboard, setLeaderboard] = useState<Array<{ email: string; name: string; points: number; approvedCases: number }>>([]);
  const [all, setAll] = useState<Array<{ email: string; name: string; points: number; approvedCases: number }>>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => { fetch("/api/points").then((response) => response.json()).then((data) => { setLeaderboard(data.leaderboard ?? []); setAll(data.all ?? []); }).finally(() => setLoading(false)); }, []);
  const canSeeAll = session.role === "manager" || session.role === "owner";
  const isRestricted = session.role === "admin" || session.role === "tester";
  const own = all[0];
  return <section className="space-y-6"><div className="rounded-2xl border border-[#dfeaff] bg-[#f4f8ff] p-6"><div className="flex items-center gap-2 text-sm font-bold text-[#3465cf]"><Trophy className="h-4 w-4" /> نظام النقاط</div><h2 className="mt-2 text-2xl font-black">{canSeeAll ? "إحصائيات فريق الإدارة" : "إحصائياتك الشخصية"}</h2><p className="mt-2 text-sm text-[#697386]">{canSeeAll ? "يمكنك متابعة أداء جميع الإداريين من الحالات المعتمدة." : "هذه الإحصائيات خاصة بحسابك. ترتيب أفضل 10 متاح للجميع."}</p></div>{isRestricted && <div className="grid gap-4 sm:grid-cols-2"><StatCard label="نقاطك المعتمدة" value={String(own?.points ?? 0)} detail="من حالاتك فقط" icon={<Trophy className="h-5 w-5 text-[#3465cf]" />} tone="bg-[#edf3ff]" /><StatCard label="حالاتك المعتمدة" value={String(own?.approvedCases ?? 0)} detail="من سجلك فقط" icon={<FileImage className="h-5 w-5 text-[#18794e]" />} tone="bg-[#e5f7ed]" /></div>}<div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">أفضل 10 من حيث النقاط</h3><p className="mt-1 text-xs text-[#9ba5b5]">هذه القائمة متاحة لكل أعضاء الإدارة</p></div>{loading ? <div className="p-8 text-center text-sm text-[#697386]">جارٍ تحميل الترتيب...</div> : leaderboard.length === 0 ? <div className="p-8 text-center text-sm text-[#697386]">لا توجد نقاط معتمدة بعد.</div> : <div className="divide-y divide-[#f0f2f5]">{leaderboard.map((person, index) => <div key={person.email} className="flex items-center gap-4 p-4"><div className={`flex h-9 w-9 items-center justify-center rounded-full text-sm font-black ${index === 0 ? "bg-[#fff0c7] text-[#a56600]" : "bg-[#edf3ff] text-[#3465cf]"}`}>{index + 1}</div><div className="flex-1"><div className="text-sm font-black">{person.name}</div><div className="mt-1 text-xs text-[#697386]">{person.approvedCases} حالات معتمدة</div></div><div className="text-left"><div className="text-xl font-black text-[#1d2736]">{person.points}</div><div className="text-[10px] text-[#9ba5b5]">نقطة</div></div></div>)}</div>}</div>{canSeeAll && <div className="rounded-2xl border border-[#e5e8ee] bg-white shadow-[0_8px_24px_rgba(22,34,58,0.04)]"><div className="border-b border-[#edf0f4] p-5"><h3 className="font-black">إحصائيات جميع الإداريين</h3><p className="mt-1 text-xs text-[#9ba5b5]">هذه القائمة متاحة للـ Manager والـ Owner فقط.</p></div>{loading ? <div className="p-8 text-center text-sm text-[#697386]">جارٍ تحميل الكشف...</div> : <div className="divide-y divide-[#f0f2f5]">{all.map((person) => <div key={person.email} className="flex items-center gap-4 p-4"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-[#e5f7ed] text-sm font-black text-[#18794e]">{person.name.slice(0, 2)}</div><div className="flex-1"><div className="text-sm font-black">{person.name}</div><div className="mt-1 text-xs text-[#697386]">{person.email}</div></div><div className="text-left"><div className="text-lg font-black">{person.points}</div><div className="text-[10px] text-[#9ba5b5]">نقطة · {person.approvedCases} معتمدة</div></div></div>)}</div>}</div>}</section>;
}

export default function Home() {
  const [session, setSession] = useState<Session | null>(null);
  const [active, setActive] = useState("الملخص");
  const [showUpload, setShowUpload] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  useEffect(() => { fetch("/api/admin/session").then((response) => response.json()).then((data) => { setSession(data.session); if (data.session?.role === "tester") setActive("بلاغات الجلتشات"); }).catch(() => setSession(null)); }, []);
  const login = async (email: string, password: string) => { const response = await fetch("/api/admin/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email, password }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error ?? "بيانات الدخول غير صحيحة"); setSession(data.session); setActive(data.session.role === "tester" ? "بلاغات الجلتشات" : "الملخص"); };
  const logout = async () => { await fetch("/api/admin/logout", { method: "POST" }); setSession(null); setActive("الملخص"); };
  const submitUpload = async () => {
    if (!selectedFile) return;
    setUploading(true); setUploadError("");
    try {
      const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("تعذر قراءة الصورة")); reader.readAsDataURL(selectedFile); });
      const response = await fetch("/api/reviews", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fileName: selectedFile.name, mimeType: selectedFile.type, dataUrl }) });
      const data = await response.json();
      if (!response.ok && response.status !== 202) throw new Error(data.error ?? "تعذر رفع الصورة");
      setShowUpload(false); setSelectedFile(null); setActive(data.review?.status === "pending_review" ? "تحتاج مراجعة" : "الحالات المرفوعة");
    } catch (error) { setUploadError(error instanceof Error ? error.message : "تعذر رفع الصورة"); } finally { setUploading(false); }
  };
  if (!session) return <LoginView onLogin={login} />;
  return <div dir="rtl" className="min-h-screen bg-[#f7f8fb] text-[#1d2736]"><aside className="fixed inset-y-0 right-0 z-20 hidden w-[246px] border-l border-[#e5e8ee] bg-white px-4 py-6 lg:block"><div className="flex items-center gap-3 px-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#3465cf] text-white"><ShieldCheck className="h-5 w-5" /></div><div><div className="font-black tracking-tight">voidsmp</div><div className="text-[10px] text-[#9ba5b5]">لوحة مراجعة الإدارة</div></div></div><nav className="mt-12 space-y-1">{[{ label: "الملخص", icon: <ArrowUpLeft /> }, { label: "الحالات المرفوعة", icon: <FileImage /> }, { label: "تحتاج مراجعة", icon: <Clock3 />, count: 0 }, { label: "الإداريون والنقاط", icon: <UsersRound /> }, { label: "تفاصيل إداري", icon: <Search />, restricted: true }, { label: "بلاغات الجلتشات", icon: <Bug />, restricted: true }, { label: "إحصائيات Testers", icon: <Trophy />, restricted: true }].map((item) => (session.role === "tester" ? (item.label === "بلاغات الجلتشات" || item.label === "إحصائيات Testers") : ((item.label !== "تفاصيل إداري" || session.role === "manager" || session.role === "owner") && (!item.restricted || session.role !== "admin"))) && <button key={item.label} onClick={() => setActive(item.label)} className={`flex w-full items-center justify-between rounded-xl px-3 py-3 text-sm font-bold transition ${active === item.label ? "bg-[#edf3ff] text-[#3465cf]" : "text-[#697386] hover:bg-[#f6f8fb]"}`}><span className="flex items-center gap-3"><span className="[&>svg]:h-[18px] [&>svg]:w-[18px]">{item.icon}</span>{item.label}</span>{item.count !== undefined && <span className="rounded-full bg-[#f1f3f6] px-2 py-0.5 text-[10px] text-[#697386]">{item.count}</span>}</button>)}</nav><div className="absolute bottom-6 right-4 left-4 rounded-2xl bg-[#f5f8ff] p-4"><div className="flex items-center gap-2 text-xs font-bold text-[#3465cf]"><CircleHelp className="h-4 w-4" /> تحتاج مساعدة؟</div><p className="mt-2 text-[11px] leading-5 text-[#697386]">راجع دليل اعتماد الحالات قبل منح النقاط.</p></div></aside><main className="lg:mr-[246px]"><header className="sticky top-0 z-10 flex h-[76px] items-center justify-between border-b border-[#e5e8ee] bg-white/90 px-5 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><button className="rounded-lg p-2 text-[#697386] lg:hidden"><Menu className="h-5 w-5" /></button><div><div className="text-xs font-bold text-[#9ba5b5]">الأحد، 25 أكتوبر 2026</div><h1 className="mt-1 text-lg font-black">{active}</h1></div></div><div className="flex items-center gap-3"><button className="relative rounded-xl border border-[#e5e8ee] p-2.5 text-[#697386]"><Bell className="h-4 w-4" /></button><div className="hidden h-8 w-px bg-[#e5e8ee] sm:block" /><div className="flex items-center gap-2"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#dce9ff] text-xs font-black text-[#2458b8]">{session.name.slice(0, 2)}</div><div className="hidden text-right sm:block"><div className="text-xs font-black">{session.name}</div><div className="text-[10px] text-[#9ba5b5]">{session.role === "owner" ? "مالك النظام" : session.role === "manager" ? "Manager" : session.role === "tester" ? "Tester" : "Admin"}</div></div></div><button onClick={logout} className="rounded-lg p-2 text-[#9ba5b5] hover:text-[#bb3a35]"><LogOut className="h-4 w-4" /></button></div></header><div className="mx-auto max-w-[1320px] px-5 py-8 sm:px-8">{active === "الإداريون والنقاط" ? <><PointsPanel session={session} />{session.role === "owner" && <div className="mt-8"><AccountsPanel session={session} /></div>}</> : active === "الحالات المرفوعة" ? <RecordsPanel title="الحالات المرفوعة" description="الحالات التي تم رفعها وتحليلها فعليًا." canOpen={session.role === "owner"} /> : active === "تحتاج مراجعة" ? <RecordsPanel title="الحالات التي تحتاج مراجعة" description="الحالات منخفضة الثقة التي تنتظر قرارًا بشريًا." review /> : active === "إحصائيات Testers" && session.role !== "admin" ? <TesterStatsPanel session={session} /> : active === "تفاصيل إداري" && (session.role === "manager" || session.role === "owner") ? <StaffDetailsPanel /> : active === "بلاغات الجلتشات" && session.role !== "admin" ? <BugReportsPanel session={session} /> : <Dashboard onUpload={() => setShowUpload(true)} />}</div></main>{showUpload && <div className="fixed inset-0 flex items-center justify-center bg-[#0d1d38]/35 px-5 backdrop-blur-sm"><div className="w-full max-w-lg rounded-3xl bg-white p-6 shadow-2xl" dir="rtl"><div className="mb-6 flex items-center justify-between"><div><h3 className="text-xl font-black">رفع حالة جديدة</h3><p className="mt-1 text-xs text-[#9ba5b5]">أرفق صورة سجل الإجراء لتحليلها</p></div><button onClick={() => { setShowUpload(false); setSelectedFile(null); }} className="rounded-lg p-2 text-[#9ba5b5]"><X className="h-5 w-5" /></button></div><div className="rounded-2xl border-2 border-dashed border-[#cdd9ee] bg-[#f8faff] px-6 py-10 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e9f0ff] text-[#3465cf]"><FileImage className="h-7 w-7" /></div><h4 className="mt-4 font-black">اسحب الصورة هنا أو اختر ملفًا</h4><p className="mt-2 text-xs text-[#9ba5b5]">PNG أو JPG أو WEBP، بحد أقصى 10MB</p><label className="mt-5 inline-flex cursor-pointer items-center rounded-xl bg-[#3465cf] px-5 py-2.5 text-xs font-bold text-white"><Upload className="ml-2 inline h-4 w-4" /> اختيار صورة<input type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(event) => { const file = event.target.files?.[0] ?? null; if (file && file.size <= 10 * 1024 * 1024) setSelectedFile(file); }} /></label>{selectedFile && <div className="mt-4 text-xs font-bold text-[#18794e]">تم اختيار: {selectedFile.name}</div>}</div>{uploadError && <div className="mt-4 rounded-xl bg-[#ffebea] p-3 text-xs font-bold text-[#bb3a35]">{uploadError}</div>}<div className="mt-5 rounded-xl bg-[#fff8ea] p-3 text-xs leading-5 text-[#8c650e]">بعد التأكيد تُحفظ الصورة، تُرسل للتحليل، وتنتقل تلقائيًا إلى الحالات المرفوعة أو المراجعة حسب درجة الثقة.</div><div className="mt-5 flex gap-3"><button type="button" onClick={() => { setShowUpload(false); setSelectedFile(null); setUploadError(""); }} className="h-11 flex-1 rounded-xl border border-[#e5e8ee] text-sm font-bold text-[#697386]">إلغاء</button><button type="button" disabled={!selectedFile || uploading} onClick={submitUpload} className="h-11 flex-1 rounded-xl bg-[#3465cf] text-sm font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">{uploading ? "جارٍ الرفع والتحليل..." : "تأكيد الرفع"}</button></div></div></div>}</div>;
}
